import json,sys
T={'notion','definition','fond','forme','effet','exception','juris','texte','idee','chapitre','lecon','section','doctrine','exemple','retenir'}
d=json.load(open(sys.argv[1]));E=[]
assert d.get('format')=='ratio' and d.get('version')==2 and d.get('kind')=='course'
cid={c['id'] for c in d['courses']};mids=set()
for m in d['maps']:
  p=m['id'];E+=[p+': id de carte en double'] if p in mids else [];mids.add(p)
  if m.get('courseId') not in cid:E.append(p+': courseId inconnu')
  if m.get('needsLayout') is not True:E.append(p+': needsLayout manquant')
  ids=[n['id'] for n in m['nodes']];S=set(ids)
  if len(S)!=len(ids):E.append(p+': id de nœud en double')
  titles=[n['title'].strip().lower() for n in m['nodes']]
  if len(set(titles))!=len(titles):E.append(p+': titres en double')
  for n in m['nodes']:
    if n.get('type') not in T:E.append(p+'/'+n['id']+': type inconnu')
    if n.get('logic') not in (None,'et','ou'):E.append(p+'/'+n['id']+': logic invalide')
  par={};eids=set()
  for e in m['edges']:
    if e['id'] in eids:E.append(p+': id d\'arête en double')
    eids.add(e['id'])
    if e['from'] not in S or e['to'] not in S or e['from']==e['to']:E.append(p+'/'+e['id']+': extrémité invalide')
    if e['kind']=='tree':
      if e['to'] in par:E.append(p+'/'+e['to']+': deux parents')
      par[e['to']]=e['from']
    elif not e.get('label'):E.append(p+'/'+e['id']+': lien sans libellé')
  roots=[i for i in ids if i not in par]
  if len(roots)!=1:E.append(p+': %d racines'%len(roots))
  for i in ids:
    seen=set();j=i
    while j in par:
      if j in seen:E.append(p+': cycle');break
      seen.add(j);j=par[j]
print('\n'.join(E) or 'OK — %d cartes, %d nœuds'%(len(d['maps']),sum(len(m['nodes']) for m in d['maps'])))
